#!/bin/bash
set -euo pipefail
test "$(id -un)" = pwa209
case "$(hostname -f)" in *.narval.calcul.quebec) ;; *) exit 2 ;; esac
python3 -B -u - <<'PY'
from pathlib import Path
import base64,json,hashlib,subprocess,shlex,os
assert os.geteuid()==3164768
r=Path('/scratch/pwa209/horsehair-worm');s=r/'maintenance/terminal-diagnostic-compaction-support-v2-20261103';s.mkdir()
payload={'compact-terminal-readers-20261103.py': '', 'test_compact_terminal_readers_20261103.py': '', 'verified-evidence-archive-20261021.py': '', 'test_verified_evidence_archive_20261021.py': ''}
pins={'compact-terminal-readers-20261103.py': '4a977c7b109d0e9df0a04308dedd7e85242aac00588e47ad30d5feb45ed4476b', 'test_compact_terminal_readers_20261103.py': '9291d7c57043821f8d31c9125c876c64a86fbe0cbf22b6d72ee5dfd879b12ffe', 'verified-evidence-archive-20261021.py': '045d8650db62c0fa52d7f56bb7bdb2669729509c23ecfbbc847e73cbbff8d42a', 'test_verified_evidence_archive_20261021.py': 'ec4131d283d3f3a792a561c6ae6324de853a4301def9d275a03018a9801f5462'}
for n,value in payload.items():
 p=s/n;p.write_bytes(base64.b64decode(value));assert hashlib.sha256(p.read_bytes()).hexdigest()==pins[n]
(s/'source-manifest.json').write_text(json.dumps(pins,indent=2))
script=s/'compact.sbatch'
text='#!/bin/bash\n#SBATCH --account=def-ptewarie_cpu\n#SBATCH --job-name=hhw-terminal-diagnostic-compaction-20261103\n#SBATCH --cpus-per-task=1\n#SBATCH --mem=16G\n#SBATCH --time=04:00:00\n#SBATCH --hold\n#SBATCH --output=/scratch/pwa209/horsehair-worm/maintenance/terminal-diagnostic-compaction-support-v2-20261103/native.log\nset -euo pipefail\nmodule load StdEnv/2023 python/3.11.5 cuda/12.6 arrow/19.0.1\nsource /home/pwa209/hhw-environment/bin/activate\nexport PYTHONPATH=/scratch/pwa209/horsehair-worm/releases/20261021-6ed201653dfa-4f3903d7c26e/src:"${PYTHONPATH:-}"\nexport PYTHONDONTWRITEBYTECODE=1 TZ=UTC OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1\ncd /scratch/pwa209/horsehair-worm/maintenance/terminal-diagnostic-compaction-support-v2-20261103\npython -s -B -m pytest test_compact_terminal_readers_20261103.py test_verified_evidence_archive_20261021.py -q -p no:cacheprovider --basetemp "$SLURM_TMPDIR/terminal-compaction-tests" --junitxml tests.xml\npython -B - <<\'CHECK\'\nimport xml.etree.ElementTree as E\nt=list(E.parse(\'tests.xml\').getroot().iter(\'testcase\'))\nassert len(t)==60 and not any(list(c.iter(k)) for c in t for k in [\'failure\',\'error\',\'skipped\'])\nCHECK\npython -s -B compact-terminal-readers-20261103.py --helper /scratch/pwa209/horsehair-worm/maintenance/terminal-diagnostic-compaction-support-v2-20261103/verified-evidence-archive-20261021.py --case /scratch/pwa209/horsehair-worm/maintenance/terminal-diagnostic-compaction-20261103 --mode compact --target-free-files 300000 --wrapper-sha256 WRAPPER_SHA\n'
text=text.replace('WRAPPER_SHA',pins['compact-terminal-readers-20261103.py']);script.write_text(text)
cmd=['sbatch','--parsable',str(script)];(s/'submit-intent.json').write_text(json.dumps(cmd))
p=subprocess.run(cmd,capture_output=True,text=True,timeout=90);(s/'submit-response.json').write_text(json.dumps({'code':p.returncode,'stdout':p.stdout,'stderr':p.stderr}));p.check_returncode();job=p.stdout.strip().split(';')[0];assert job.isdigit()
p=subprocess.run(['scontrol','show','job',job,'-o'],capture_output=True,text=True,timeout=90);p.check_returncode();f=dict(x.split('=',1) for x in shlex.split(p.stdout) if '=' in x)
assert f['JobId']==job and f['UserId']=='pwa209(3164768)' and f['JobState']=='PENDING' and f['Reason']=='JobHeldUser' and f['Command']==str(script) and f['JobName']=='hhw-terminal-diagnostic-compaction-20261103' and f['NumCPUs']=='1' and f['MinMemoryNode'] in ['16G','16384M'] and f['TimeLimit']=='04:00:00'
(s/'held-native.json').write_text(json.dumps(f));(s/'release-intent.json').write_text(json.dumps(['scontrol','release',job]))
p=subprocess.run(['scontrol','release',job],capture_output=True,text=True,timeout=90);(s/'release-response.json').write_text(json.dumps({'code':p.returncode,'stdout':p.stdout,'stderr':p.stderr}))
p=subprocess.run(['scontrol','show','job',job,'-o'],capture_output=True,text=True,timeout=90);p.check_returncode();f=dict(x.split('=',1) for x in shlex.split(p.stdout) if '=' in x)
assert f['JobId']==job and f['UserId']=='pwa209(3164768)' and f['Command']==str(script) and (f['JobState']=='RUNNING' or f['JobState']=='PENDING' and f['Reason'] not in ['JobHeldUser','JobHeldAdmin'] and int(f['Priority'])>0)
(s/'registration.json').write_text(json.dumps({'job_id':job,'actual_unheld':f},indent=2));print('COMPACTOR_REGISTRATION '+job,flush=True)
PY
